import { openStore } from "./db.js";
import { schemaSnapshot } from "./migrate.js";

export const SCHEMA_SNAPSHOT_FILE = new URL(
  "../../../data/schema.sql",
  import.meta.url,
);

const HEADER = [
  "-- Generated by `npm run db -- schema` from apps/backend/src/migrations.",
  "-- Reference only; do not edit. Change the schema with a new migration.",
  "",
  "",
].join("\n");

/** The schema produced by applying every migration to an empty database. */
export async function renderSchemaSnapshot(): Promise<string> {
  const store = await openStore(":memory:");
  try {
    return HEADER + schemaSnapshot(store);
  } finally {
    store.db.close();
  }
}
